package main

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"regexp"

	"github.com/jackc/pgx/v5"
)

var (
	loginName = regexp.MustCompile(`^[a-z_][a-z0-9_]{0,62}$`)
	// The password is generated by Secrets Manager without punctuation, so it
	// can be written as a SQL literal without escaping (CREATE ROLE does not
	// take bind parameters). Anything else is refused rather than escaped.
	loginPassword = regexp.MustCompile(`^[A-Za-z0-9]{32,128}$`)
)

// ensureLogin creates (or, on a later run, updates the password of) the
// login role the services connect as. Its only privilege is membership of
// ferry_app, the NOLOGIN role the migrations grant to (00002_app_role.sql),
// so the services keep exactly ferry_app's least-privilege grants. It
// refuses to touch a role that holds any other power, such as the RDS
// master user, so a wrong name cannot reset an administrator's password.
func ensureLogin(ctx context.Context, db *sql.DB, name, password string) error {
	if !loginName.MatchString(name) || name == "ferry_app" {
		return fmt.Errorf("app login %q: want a lowercase role name other than ferry_app", name)
	}
	if !loginPassword.MatchString(password) {
		return errors.New("FERRY_APP_DB_PASSWORD: want 32 to 128 letters and digits")
	}
	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("begin: %w", err)
	}
	defer func() { _ = tx.Rollback() }()

	// An existing role must hold no power of its own: no administrative
	// attribute, no membership other than ferry_app (on RDS the master
	// user's power comes from rds_superuser membership, and roles such as
	// pg_write_all_data bypass the ledger's grants), and no owned objects
	// (an owner has every right on what it owns). Otherwise resetting its
	// password would hand that power to every service (SA-005).
	var exists, attrs, member, owner bool
	err = tx.QueryRowContext(ctx, `
		SELECT true,
		       r.rolsuper OR r.rolcreaterole OR r.rolcreatedb OR r.rolreplication OR r.rolbypassrls,
		       EXISTS (SELECT 1 FROM pg_auth_members m JOIN pg_roles g ON g.oid = m.roleid
		               WHERE m.member = r.oid AND g.rolname <> 'ferry_app'),
		       EXISTS (SELECT 1 FROM pg_class c WHERE c.relowner = r.oid)
		       OR EXISTS (SELECT 1 FROM pg_namespace n WHERE n.nspowner = r.oid)
		       OR EXISTS (SELECT 1 FROM pg_database d WHERE d.datdba = r.oid)
		FROM pg_roles r WHERE r.rolname = $1`, name).Scan(&exists, &attrs, &member, &owner)
	switch {
	case errors.Is(err, sql.ErrNoRows):
	case err != nil:
		return fmt.Errorf("look up role %s: %w", name, err)
	case attrs:
		return fmt.Errorf("role %s has administrative attributes; refusing to use it as the app login", name)
	case member:
		return fmt.Errorf("role %s is a member of a role other than ferry_app; refusing to use it as the app login", name)
	case owner:
		return fmt.Errorf("role %s owns database objects; refusing to use it as the app login", name)
	}

	ident := pgx.Identifier{name}.Sanitize()
	literal := "'" + password + "'" // safe: password is [A-Za-z0-9] only
	stmts := []string{
		"CREATE ROLE " + ident + " LOGIN PASSWORD " + literal + " IN ROLE ferry_app",
	}
	if exists {
		stmts = []string{
			"ALTER ROLE " + ident + " WITH LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS PASSWORD " + literal,
			"GRANT ferry_app TO " + ident,
		}
	}
	for _, s := range stmts {
		// CREATE/ALTER ROLE take no bind parameters. The name is checked
		// against loginName and quoted with pgx.Identifier; the password is
		// checked against loginPassword (letters and digits only).
		if _, err := tx.ExecContext(ctx, s); err != nil { //nolint:gosec // G701: inputs allowlisted above, see comment
			// The statement holds the password: report only which step failed.
			return fmt.Errorf("set up app login %s: %w", name, pgErrCode(err))
		}
	}
	if err := tx.Commit(); err != nil {
		return fmt.Errorf("commit app login %s: %w", name, pgErrCode(err))
	}
	return nil
}

// pgErrCode keeps the error class but drops text that might echo the
// statement.
func pgErrCode(err error) error {
	var pe interface{ SQLState() string }
	if errors.As(err, &pe) {
		return fmt.Errorf("postgres error %s", pe.SQLState())
	}
	return errors.New("statement failed")
}
